coefs=[np.polyfit(cam[:,c],pal[:,c],2) for c in range(3)]
def rectify(path,n=256):
    a=np.array(Image.open(path).crop((68,68,956,956)).resize((n,n),Image.Resampling.LANCZOS)).astype(float)
    for c in range(3):a[:,:,c]=np.polyval(coefs[c],a[:,:,c])
    return np.clip(a,0,255)
def metrics(a,t):
    A=lab(nd.gaussian_filter(a,(1.126,1.126,0)));T=lab(nd.gaussian_filter(t,(1.126,1.126,0)))
    de=np.linalg.norm(A-T,axis=-1);s=(slice(10,-10),slice(10,-10))
    x=A[:,:,0];y=T[:,:,0];mx=nd.gaussian_filter(x,1.69);my=nd.gaussian_filter(y,1.69)
    vx=nd.gaussian_filter(x*x,1.69)-mx*mx;vy=nd.gaussian_filter(y*y,1.69)-my*my;cov=nd.gaussian_filter(x*y,1.69)-mx*my
