    gx=np.hypot(*np.gradient(x));gy=np.hypot(*np.gradient(y));edge=np.corrcoef(gx[s].ravel(),gy[s].ravel())[0,1]
    return dict(mean=float(de[s].mean()),p90=float(np.percentile(de[s],90)),ssim=float(ss),edge=float(edge))
